from scipy.optimize import least_squares
def mk(model):
    def f(p):
        return model(p)-y
    return f
structs={
 'pow t,pow A': lambda p: p[0]*np.log(1+p[1]*t)*A**2 + p[2]*t**p[3]*A**p[4] + p[5]*A**p[6] ,
 'exp t,pow A': lambda p: p[0]*np.log(1+p[1]*t)*A**2 + p[2]*np.exp(-p[3]*t)*A**p[4] + p[5]*A**p[6],
 'pow t, pow A, A-only t-decay': lambda p: p[0]*np.log(1+p[1]*t)*A**2 + p[2]*t**p[3]*A**p[4] + p[5]*np.exp(-p[6]*t)*A**p[7],
 'inv(1+bt)^a A^p': lambda p: p[0]*np.log(1+p[1]*t)*A**2 + p[2]*(1+p[3]*t)**(-p[4])*A**p[5] + p[6]*A**p[7],
}
rng=np.random.default_rng(0)
for name,m in structs.items():
    n=len(structs[name].__code__.co_varnames) if False else None
    bestf=None
    npar={'pow t,pow A':7,'exp t,pow A':7,'pow t, pow A, A-only t-decay':8,'inv(1+bt)^a A^p':8}[name]
